                .andExpect(jsonPath("$.code").value("TASK_CANCELLED"));
        mockMvc.perform(post("/api/tasks/" + t3 + "/receipt").contentType("application/json")
                        .content("{\"requestId\":\"r-rc3\",\"result\":\"SUCCESS\"}"))
                .andExpect(status().isConflict());
