```java
package com.example.starter.firmware;

import java.time.Clock;
import java.time.Instant;
import java.time.ZoneId;

/** 测试用可控时钟：可定点、可步进。 */
public class MutableClock extends Clock {
    private Instant instant;
    private final ZoneId zone;

    public MutableClock(Instant instant, ZoneId zone) { this.instant = instant; this.zone = zone; }
    public synchronized void setInstant(Instant newInstant) { this.instant = newInstant; }
    public synchronized void advanceSeconds(long seconds) { this.instant = this.instant.plusSeconds(seconds); }
    @Override public synchronized Instant instant() { return instant; }
    @Override public ZoneId getZone() { return zone; }
    @Override public Clock withZone(ZoneId newZone) { return new MutableClock(instant(), newZone); }
}
```

